let activityState=null,activityLoading=false,gameRun=null,gameTimer=null,gameStart=0;
const levelSteps=[0,100,250,450,700,950,1200,1800,2500,3300];
const levelNames=['인턴 새내기','업무 입문자','자료 수집가','체크리스트 실천가','용어 학습자','문서 탐색가','등기부 탐험가','업무 숙련가','인턴 길잡이','퀘스트 마스터'];
function levelOf(xp){return Math.max(0,levelSteps.findLastIndex(x=>xp>=x));}
async function activityRequest(path,data){const r=await fetch('/api/'+path,{credentials:'same-origin',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})});const result=await r.json();if(!r.ok)throw Error(result.error||'연결을 확인해 주세요.');return result;}
async function loadActivity(){if(activityLoading||!window.hfAuth)return;activityLoading=true;try{activityState=await activityRequest('activity');paintActivity();showAnnouncementAlert();}catch(e){const note=document.querySelector('.notice');if(note)note.textContent=e.message;}finally{activityLoading=false;}}
function memberRows(rows,type){return rows.length?rows.map((r,i)=>`<div class="row ranking-row ${r.id===window.hfAuth.user.id?'my-ranking':''}"><strong>${i+1}</strong><span>${esc(r.name)}</span><small>${type==='reflex'?r.ms+' ms':Number(r.xp)+' XP'}</small></div>`).join(''):'<p class="muted">아직 기록이 없습니다.</p>';}
function cleaningMarkup(full=false){
 if(!activityState)return '<p>담당 구역을 확인 중입니다…</p>';
 const admin=window.hfAuth.user.role==='admin',a=activityState;
 return `<p class="muted">${a.week} 시작 주간</p>`+a.cleaning.map(j=>`<div class="row"><span><strong>${esc(j.name)}</strong><br><small>${esc(j.area)}</small></span><small>${j.done?'완료':'진행 전'}</small>${!j.done&&(admin||j.user_id===window.hfAuth.user.id)?`<button type="button" class="primary cleaning-action" data-id="${j.id}" data-action="complete">완료</button>`:''}${admin&&full?`<button type="button" class="auth-link cleaning-action" data-id="${j.id}" data-action="remove">배정 삭제</button>`:''}</div>`).join('')+(a.cleaning.length?'':'<p>이번 주 청소 당번이 아직 설정되지 않았습니다.</p>')+(full&&admin?`<form id="cleaning-form" class="toolbar"><label>담당자<select class="field" name="user_id">${a.members.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><label>담당 구역<input class="field" name="area" maxlength="80" placeholder="예: 탕비실" required></label><button class="primary">이번 주 배정 추가</button><p class="board-status" role="status"></p></form>`:full?'':`<a href="#cleaning" class="board-source">주간 당번 관리 →</a>`);
}
function paintActivity(){
 const content=document.querySelector('#content');if(!content)return;
 const route=location.hash.slice(1);const a=activityState;
 if(route==='cleaning'){content.innerHTML=`<h1 class="view-title">금주 청소 담당자</h1>${panel('이번 주 청소 배정',cleaningMarkup(true))}`;return;}
 if(route==='reflex'){
  if(!content.querySelector('#reflex-play'))content.innerHTML=`<h1 class="view-title">순발력 대결</h1>${panel('반응속도 테스트','<p>시작 후 버튼이 노란색으로 바뀌면 누르세요. 너무 빨리 누르면 기록되지 않습니다.</p><button type="button" id="reflex-play">눌러서 시작</button><p id="reflex-message" role="status"></p>')}${panel('이번 주 참여자 랭킹','<div id="reflex-ranking"></div>')}`;
  content.querySelector('#reflex-ranking').innerHTML=a?memberRows(a.reflex,'reflex'):'기록을 불러오는 중…';return;
 }
 if(route)return;
 const hero=content.firstElementChild;hero.classList.add('live-hero');const xp=Number(a?.xp||0),level=levelOf(xp),next=levelSteps[level+1],progress=next?Math.min(100,(xp-levelSteps[level])/(next-levelSteps[level])*100):100;
 const badges=[['첫 출석',(attendance?.total||0)>=1],['7일 연속 출석',(attendance?.streak||0)>=7],['100 XP 달성',xp>=100],['첫 청소 완료',(a?.clean_done||0)>0]];
 hero.innerHTML=`<div class="hero-summary"><p>HF 인턴 포털</p><h1>${esc(window.hfAuth.user.name)} 인턴님, 오늘도 함께 성장해요!</h1><div class="hero-tags"><button class="progress-link" data-progress="level">Lv.${level+1} ${levelNames[level]}</button><button class="progress-link" data-progress="attendance">${attendance?.streak||0}일 연속 출석</button><button class="progress-link" data-progress="badges">뱃지 ${badges.filter(x=>x[1]).length}개</button></div><div class="xp-label"><span>경험치</span><span>${xp} / ${next||'최고 레벨'} XP</span></div><div class="xp-track" role="progressbar" aria-label="다음 레벨까지 경험치" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(progress)}"><div style="width:${progress}%"></div></div><p>${next?`Lv.${level+2}까지 ${next-xp} XP 남았어요`:'최고 레벨에 도달했어요!'}</p></div><div class="hero-milestones">${badges.map(([name,on])=>`<button type="button" data-progress="badges" class="milestone ${on?'earned':''}"><span aria-hidden="true">${on?'✓':'○'}</span>${name}</button>`).join('')}</div>`;
 for(const section of content.querySelectorAll('section')){
  const heading=section.querySelector('h2');if(!heading)continue;const title=heading.textContent.trim();
  if(title==='이번 달 랭킹')section.innerHTML='<h2>이번 달 랭킹</h2>'+ (a?`<p class="muted">${a.month} · 15초마다 갱신</p>`+memberRows(a.ranking,'xp'):'기록 확인 중…');
  if(title.startsWith('금주 청소 당번')){section.classList.add('cleaning-duty-card');const names=[...new Set((a?.cleaning||[]).map(j=>j.name))];section.innerHTML='<div class="cleaning-duty-heading"><span class="cleaning-duty-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="m15 3-5 8m-2-1 7 4-5 7-7-4 5-7Z"/><path d="m6 15-2 3m5-1-2 3m11-12v4m-2-2h4"/></svg></span><h2>금주 청소 당번</h2></div><div class="cleaning-duty-names">'+(names.length?names.map(n=>'<span class="cleaning-name-badge">'+esc(n)+'</span>').join(''):'<span class="cleaning-duty-empty">아직 배정되지 않았어요</span>')+'</div>';}
  if(title==='순발력 대결'){const mine=a?.reflex.find(r=>r.id===window.hfAuth.user.id);section.classList.add('dashboard-reflex-card');section.innerHTML='<h2>순발력 대결</h2>'+
`<p>내 이번 주 최고 기록: ${mine?mine.ms+' ms':'아직 기록 없음'}</p>`+(a?memberRows(a.reflex,'reflex'):'기록 확인 중…')+'<div class="reflex-card-actions"><a href="#reflex" class="primary reflex-card-button">도전하기</a></div>';}
 }
 for(const span of content.querySelectorAll('a span'))if(/^\+\d+ XP/.test(span.textContent.trim()))span.textContent='메뉴 바로가기';
 for(const span of content.querySelectorAll('a span'))if(span.textContent.trim()==='최고 기록 시 보너스')span.textContent='이번 주 기록 경쟁';
 let announcements=content.querySelector('#dashboard-announcements');if(!announcements){announcements=document.createElement('section');announcements.id='dashboard-announcements';announcements.className='panel';hero.after(announcements);}announcements.innerHTML='<h2>전체 공지</h2>'+announcementRows(false);
 const calendar=content.querySelector('#dashboard-calendar');if(calendar)calendar.innerHTML=calendarMarkup();
}
function activityProgress(type){
 const xp=Number(activityState?.xp||0),level=levelOf(xp);let dialog=document.querySelector('#progress-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='progress-dialog';document.body.append(dialog);}dialog.setAttribute('aria-labelledby','progress-title');
 const badges=[['첫 출석',(attendance?.total||0)>=1,'출석체크 1회'],['7일 연속 출석',(attendance?.streak||0)>=7,'7일 연속 출석'],['100 XP 달성',xp>=100,'누적 포인트 100점'],['첫 청소 완료',(activityState?.clean_done||0)>0,'이번 주 배정 구역 완료']];
 dialog.innerHTML=`<div class="progress-dialog-head"><h2 id="progress-title">${type==='level'?'레벨과 포인트':'내 뱃지'}</h2><button class="auth-link">닫기</button></div>`+(type==='level'?`<p>현재 ${xp} XP · Lv.${level+1}</p><p class="muted">출석 10점 · 업무 완료 5점(하루 최대 5건) · 공부 모임 개설 10점(하루 1회) · 모임 참여 5점(모임당 1회) · 건의 5점(하루 1회) · 청소 완료 10점</p>`+levelNames.map((n,i)=>`<div class="progress-row ${i===level?'current-stage':''}"><strong>Lv.${i+1} ${n}</strong><span>${levelSteps[i]} XP</span></div>`).join(''):badges.map(([name,on,rule])=>`<div class="progress-row ${on?'current-stage':''}"><strong>${name}</strong><span>${on?'획득':'미획득'} · ${rule}</span></div>`).join(''));
 dialog.querySelector('button').onclick=()=>dialog.close();dialog.showModal();
}
document.addEventListener('submit',async e=>{if(e.target.id!=='cleaning-form')return;e.preventDefault();const form=e.target,d=Object.fromEntries(new FormData(form)),button=form.querySelector('button');button.disabled=true;try{await activityRequest('cleaning/assign',{user_id:Number(d.user_id),area:d.area});await loadActivity();}catch(error){form.querySelector('.board-status').textContent=error.message;button.disabled=false;}});
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.classList.contains('cleaning-action')){b.disabled=true;try{await activityRequest('cleaning/'+b.dataset.action,{id:Number(b.dataset.id)});await loadActivity();}catch(error){b.disabled=false;note.textContent=error.message;}return;}
 if(b.id!=='reflex-play')return;const msg=document.querySelector('#reflex-message');
 if(gameRun?.ready){const ms=Math.round(performance.now()-gameStart),token=gameRun.token;gameRun=null;b.classList.remove('ready');b.disabled=true;try{await activityRequest('reflex/result',{token,ms});msg.textContent=`이번 기록 ${ms} ms`;await loadActivity();}catch(error){msg.textContent=error.message;}finally{b.disabled=false;b.textContent='다시 도전하기';}return;}
 if(gameRun){clearTimeout(gameTimer);gameRun=null;b.textContent='너무 빨라요! 다시 시작';msg.textContent='노란색으로 바뀐 뒤 눌러 주세요.';return;}
 b.disabled=true;try{gameRun=await activityRequest('reflex/start',{});b.disabled=false;b.textContent='기다려 주세요…';gameTimer=setTimeout(()=>{if(!b.isConnected||!gameRun)return;gameRun.ready=true;gameStart=performance.now();b.classList.add('ready');b.textContent='지금!';},gameRun.delay);}catch(error){b.disabled=false;msg.textContent=error.message;}
});
window.addEventListener('hashchange',()=>{clearTimeout(gameTimer);gameRun=null;});
setInterval(()=>{if(!document.hidden)loadActivity();},15000);

function announcementRows(manage){const rows=activityState?.announcements||[];return rows.length?rows.map(p=>`<article class="announcement-item"><h3>${esc(p.title)}</h3><small>${esc(p.created.slice(0,10))}</small><p class="board-body">${esc(p.body)}</p>${manage?`<button type="button" class="task-delete" data-notice-delete="${p.id}">공지 삭제</button>`:announcementCheck(p.id)}</article>`).join(''):'<p class="muted">등록된 공지가 없습니다.</p>';}
const announcementSeenMemory=new Map(),announcementShown=new Set();
function announcementSeen(){const key='hf-notices-seen:'+window.hfAuth.user.id;let ids=announcementSeenMemory.get(key)||[];try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))ids=[...new Set([...ids,...saved])];}catch{}return {key,ids};}
function announcementCheck(id){return `<label class="notice-check"><input type="checkbox" data-notice-read="${id}" ${announcementSeen().ids.includes(id)?'checked':''}> 확인했어요</label>`;}
function setAnnouncementRead(id,checked){const {key,ids}=announcementSeen(),seen=checked?[...new Set([...ids,id])]:ids.filter(x=>x!==id);announcementSeenMemory.set(key,seen);try{localStorage.setItem(key,JSON.stringify(seen));}catch{}}
document.addEventListener('change',e=>{const input=e.target.closest('[data-notice-read]');if(!input)return;setAnnouncementRead(Number(input.dataset.noticeRead),input.checked);document.querySelectorAll(`[data-notice-read="${input.dataset.noticeRead}"]`).forEach(other=>other.checked=input.checked);});
function showAnnouncementAlert(){
 if(!window.hfAuth||document.hidden||document.querySelector('dialog[open]'))return;
 const {key,ids}=announcementSeen(),unread=(activityState?.announcements||[]).filter(p=>!ids.includes(p.id)&&!announcementShown.has(key+':'+p.id));if(!unread.length)return;
 let modal=document.querySelector('#announcement-alert');if(!modal){modal=document.createElement('dialog');modal.id='announcement-alert';modal.setAttribute('aria-labelledby','announcement-alert-title');document.body.append(modal);}
 modal.innerHTML=`<div class="announcement-alert-heading"><span aria-hidden="true">●</span><h2 id="announcement-alert-title">새 전체 공지가 도착했어요</h2></div><p class="muted">읽은 공지마다 확인 체크를 해 주세요.</p>${unread.map(p=>`<article class="announcement-item"><h3>${esc(p.title)}</h3><small>${esc(p.created.slice(0,10))}</small><p class="board-body">${esc(p.body)}</p>${announcementCheck(p.id)}</article>`).join('')}<button type="button" class="primary announcement-confirm">닫기</button>`;
 modal.oncancel=e=>{e.preventDefault();modal.querySelector('button').click();};
 modal.querySelector('button').onclick=()=>modal.close();unread.forEach(p=>announcementShown.add(key+':'+p.id));modal.showModal();
}
function showAnnouncements(){let modal=document.querySelector('#announcements-dialog');if(!modal){modal=document.createElement('dialog');modal.id='announcements-dialog';document.body.append(modal);}modal.innerHTML=`<div class="progress-dialog-head"><h2>전체 공지 관리</h2><button type="button" class="auth-link" data-close-dialog>닫기</button></div><form id="announcement-form" class="board-form"><label>제목<input class="field" name="title" maxlength="120" required></label><label>내용<textarea class="field" name="body" maxlength="5000" rows="5" required></textarea></label><button class="primary">전체 회원에게 공지</button><p class="board-status" role="status"></p></form>${announcementRows(true)}`;modal.querySelector('[data-close-dialog]').onclick=()=>modal.close();if(!modal.open)modal.showModal();}
function showCalendarEvents(day){let modal=document.querySelector('#calendar-events-dialog');if(!modal){modal=document.createElement('dialog');modal.id='calendar-events-dialog';document.body.append(modal);}modal.dataset.day=day;modal.innerHTML=`<div class="progress-dialog-head"><h2>${esc(day)} 개인 일정</h2><button type="button" class="auth-link" data-close-dialog>닫기</button></div><p class="muted">이 일정은 본인만 볼 수 있습니다.</p>`+(activityState?.events||[]).filter(x=>x.day===day).map(x=>`<div class="event-item"><p>${esc(x.body)}</p><button type="button" class="task-delete" data-event-delete="${x.id}">삭제</button></div>`).join('')+`<form id="calendar-event-form" class="board-form"><label>일정 메모<textarea class="field" name="body" maxlength="1000" rows="3" required placeholder="시간과 일정을 적어 주세요"></textarea></label><button class="primary">일정 추가</button><p class="board-status" role="status"></p></form>`;modal.querySelector('[data-close-dialog]').onclick=()=>modal.close();if(!modal.open)modal.showModal();}
async function refreshAfterEdit(){while(activityLoading)await new Promise(resolve=>setTimeout(resolve,100));await loadActivity();}
document.addEventListener('submit',async e=>{const form=e.target;if(!['announcement-form','calendar-event-form'].includes(form.id))return;e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const d=Object.fromEntries(new FormData(form));if(form.id==='announcement-form'){await activityRequest('announcements/post',d);await refreshAfterEdit();showAnnouncements();}else{const day=form.closest('dialog').dataset.day;await activityRequest('calendar/post',{day,body:d.body});await refreshAfterEdit();showCalendarEvents(day);}}catch(error){form.querySelector('.board-status').textContent=error.message;button.disabled=false;}});
document.addEventListener('click',async e=>{const day=e.target.closest('[data-event-day]');if(day){showCalendarEvents(day.dataset.eventDay);return;}const b=e.target.closest('[data-event-delete],[data-notice-delete]');if(!b)return;b.disabled=true;try{const calendar=b.dataset.eventDelete!==undefined,day=b.closest('dialog')?.dataset.day;await activityRequest(calendar?'calendar/remove':'announcements/remove',{id:Number(calendar?b.dataset.eventDelete:b.dataset.noticeDelete)});await refreshAfterEdit();if(calendar)showCalendarEvents(day);else showAnnouncements();}catch(error){b.disabled=false;const msg=document.createElement('p');msg.textContent=error.message;msg.setAttribute('role','alert');b.after(msg);}});
